<?php require_once __DIR__.'/../includes/auth.php'; require_login(); verify_csrf(); $id=(int)($_POST['order_id']??0);$action=$_POST['action']??'';$stmt=$pdo->prepare('SELECT * FROM orders WHERE id=? AND user_id=? LIMIT 1');$stmt->execute([$id,$_SESSION['user_id']]);$order=$stmt->fetch();if(!$order){flash('Order not found.','error');header('Location: ../orders.php');exit;}if($action==='cancel'&&!in_array($order['status'],['delivered','cancelled'],true)){ $pdo->prepare("UPDATE orders SET status='cancelled' WHERE id=?")->execute([$id]);flash('Order cancelled.');}else{flash('This order cannot be changed.','error');}header('Location: ../orders.php');exit;
